<?php declare(strict_types=1); namespace App\Tests\Imperium\Runtime;
use App\Imperium\Runtime\LaCortine\DeterministicTransitionCallerAuthorityIssuanceService; use PHPUnit\Framework\TestCase;
final class ProviderBindingActivationPrincipalProvenanceBatch6Test extends TestCase { use IronGateCallerAuthorityTestTrait; private string $root;
protected function setUp():void{$this->root=sys_get_temp_dir().'/imperium-ppr-b6-'.bin2hex(random_bytes(6));mkdir($this->root,0770,true);$this->writeImperatorPrincipal();}
protected function tearDown():void{if(!is_dir($this->root))return;$i=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($this->root,\FilesystemIterator::SKIP_DOTS),\RecursiveIteratorIterator::CHILD_FIRST);foreach($i as$x)$x->isDir()?rmdir($x->getPathname()):unlink($x->getPathname());rmdir($this->root);}
public function testCanonicalGenerationTransitionAndTargetHaveOneIssuanceWinner():void{$s=new DeterministicTransitionCallerAuthorityIssuanceService($this->root);$t=['id'=>'decision-test','digest'=>str_repeat('a',64)];$at=new \DateTimeImmutable('2026-08-29T21:00:00+00:00');$a=$s->issueImperator($this->imperatorPrincipalId,'ISSUE_EXACT_PROVIDER_BINDING_ACTIVATION_AUTHORITY',$t,$at,$at->modify('+5 minutes'));self::assertSame($a,$s->issueImperator($this->imperatorPrincipalId,'ISSUE_EXACT_PROVIDER_BINDING_ACTIVATION_AUTHORITY',$t,$at,$at->modify('+5 minutes')));$this->expectExceptionMessage('PST111_IMMUTABLE_RECORD_CONFLICT');$s->issueImperator($this->imperatorPrincipalId,'ISSUE_EXACT_PROVIDER_BINDING_ACTIVATION_AUTHORITY',$t,$at->modify('+1 second'),$at->modify('+5 minutes 1 second'));}
public function testDocumentationAuthorizesLifecycleEnforcementOnlyNext():void{$h=(string)file_get_contents(dirname(__DIR__,3).'/docs/handoffs/provider-binding-activation-principal-provenance-remediation-batch-6-complete.md');foreach(['Only Batch 7 is authorized','read-only reconstruction and lifecycle enforcement','suspension','revocation','supersession','expiry','retirement','may not reconsider corridor disposition','external I/O','Iron Gate','Lazaretto']as$b)self::assertNotFalse(stripos($h,$b),$b);}}
